"""Shared explicit-input notebook plumbing; source/environment records never gate execution."""
from pathlib import Path
import ast,json
ROOT=Path(__file__).resolve().parents[1]
SETUP = "from pathlib import Path\nimport datetime,json,os,signal,subprocess,sys,time,traceback\nif CONFIG_PATH is None:\n    raise ValueError('Set CONFIG_PATH to an explicit readable configuration JSON; no historical Drive input is implicit')\nCONFIG_PATH=Path(CONFIG_PATH).expanduser().resolve()\ndef validate_config():\n    cfg=json.loads(CONFIG_PATH.read_text())\n    if cfg.get('name')!=CONFIG_NAME:raise ValueError('configuration name does not belong to this fixed entrypoint')\n    if cfg.get('fixed_denominator')!=FIXED:raise ValueError('configuration fixed denominator mismatch')\n    return cfg\nSTAMP=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')\nOUTPUT=Path(OUTPUT_ROOT)/STAMP\nOUTPUT.mkdir(parents=True,exist_ok=False)\nRUN_OUTPUT=OUTPUT/'fixed_reference'\nREPO=Path(SOURCE_DIR).expanduser().resolve()\nPYTHON=sys.executable\ndef write_json(path,value):\n    tmp=path.with_suffix(path.suffix+'.tmp');tmp.write_text(json.dumps(value,indent=2)+'\\n');os.replace(tmp,path)\ndef failed(stage,exc):\n    captured_traceback=''.join(traceback.format_exception(type(exc),exc,exc.__traceback__))\n    write_json(OUTPUT/'setup_failure.json',dict(stage=stage,error=f'{type(exc).__name__}: {exc}',traceback=captured_traceback,fixed_denominator=FIXED))\ndef logged(command,stage,cwd=None,check=True):\n    child=None;code=None;primary=None;primary_tb=None;cleanup_errors=[]\n    def retain_cleanup_error(label,exc):\n        nonlocal primary,primary_tb\n        if primary is None and not isinstance(exc,Exception):\n            primary=exc;primary_tb=exc.__traceback__\n        else:\n            cleanup_errors.append(label+': '+repr(exc))\n    try:\n        with (OUTPUT/'execution.log').open('a') as log:\n            log.write('COMMAND '+repr(command)+'\\n');log.flush()\n            popen_group={'start_new_session':True} if os.name=='posix' else {}\n            child=subprocess.Popen(command,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1,**popen_group)\n            try:\n                for line in child.stdout:\n                    print(line,end='',flush=True);log.write(line);log.flush()\n                code=child.wait()\n            except BaseException as exc:\n                primary=exc;primary_tb=exc.__traceback__\n            finally:\n                if child is not None:\n                    if os.name=='posix':\n                        pgid=child.pid\n                        try:os.killpg(pgid,signal.SIGTERM)\n                        except ProcessLookupError:pass\n                        except BaseException as exc:retain_cleanup_error('group SIGTERM',exc)\n                        try:\n                            deadline=time.monotonic()+5.0\n                            while time.monotonic()<deadline:\n                                try:os.killpg(pgid,0)\n                                except ProcessLookupError:break\n                                except BaseException as exc:\n                                    retain_cleanup_error('group probe',exc);break\n                                time.sleep(0.05)\n                        except BaseException as exc:\n                            retain_cleanup_error('group TERM grace',exc)\n                        finally:\n                            try:os.killpg(pgid,signal.SIGKILL)\n                            except ProcessLookupError:pass\n                            except BaseException as exc:retain_cleanup_error('group SIGKILL',exc)\n                    elif child.poll() is None:\n                        try:child.terminate()\n                        except ProcessLookupError:pass\n                        except BaseException as exc:retain_cleanup_error('terminate',exc)\n                    try:\n                        try:code=child.wait(timeout=10)\n                        except subprocess.TimeoutExpired:\n                            try:child.kill()\n                            except ProcessLookupError:pass\n                            except BaseException as exc:retain_cleanup_error('kill',exc)\n                            try:code=child.wait(timeout=10)\n                            except BaseException as exc:retain_cleanup_error('wait after kill',exc)\n                        except BaseException as exc:retain_cleanup_error('wait',exc)\n                    finally:\n                        if child.stdout is not None:\n                            try:child.stdout.close()\n                            except BaseException as exc:retain_cleanup_error('stdout close',exc)\n            if primary is None and not cleanup_errors:\n                log.write('EXIT '+str(code)+'\\n');log.flush()\n    except BaseException as wrapper_error:\n        if primary is None:\n            primary=wrapper_error;primary_tb=wrapper_error.__traceback__\n        elif wrapper_error is not primary:\n            cleanup_errors.append('log wrapper/close: '+repr(wrapper_error))\n    if primary is None and cleanup_errors:\n        primary=RuntimeError('process cleanup failed: '+'; '.join(cleanup_errors))\n        primary_tb=primary.__traceback__\n    if primary is None and check and code:\n        primary=subprocess.CalledProcessError(code,command)\n        primary_tb=primary.__traceback__\n    if primary is not None:\n        if cleanup_errors and hasattr(primary,'add_note'):\n            primary.add_note('secondary cleanup errors: '+'; '.join(cleanup_errors))\n        try:failed(stage,primary)\n        except BaseException as record_error:\n            if hasattr(primary,'add_note'):primary.add_note('failure record error: '+repr(record_error))\n        raise primary.with_traceback(primary_tb)\n    return code\nwrite_json(OUTPUT/'setup_receipt.json',dict(status='SETUP_STARTED',fixed_denominator=FIXED))\ndef optional_record(path,value):\n    try:write_json(path,value)\n    except Exception as exc:print('Optional record unavailable:',path,type(exc).__name__,str(exc))\n"

ENVIRONMENT = 'try:\n    if not REPO.exists():\n        if not SOURCE_URL:raise FileNotFoundError(\'Provide available source at SOURCE_DIR or explicitly set SOURCE_URL\')\n        logged([\'git\',\'clone\',SOURCE_URL,str(REPO)],\'SOURCE_CLONE\')\n    entry=REPO.joinpath(*ENTRYPOINT.split(\'.\')).with_suffix(\'.py\')\n    if not entry.is_file():raise FileNotFoundError(\'Required runner is unavailable in SOURCE_DIR: \'+str(entry))\n    INPUT_CONFIG=validate_config()\n    if REQUIRES_MEDIA:\n        import shutil\n        if any(shutil.which(n) is None for n in (\'ffmpeg\',\'ffprobe\')):\n            logged([\'apt-get\',\'update\'],\'MEDIA_TOOL_UPDATE\',check=False)\n            logged([\'apt-get\',\'install\',\'-y\',\'ffmpeg\'],\'MEDIA_TOOL_REPAIR\')\n        logged([\'ffmpeg\',\'-version\'],\'FFMPEG_PROBE\')\n        logged([\'ffprobe\',\'-version\'],\'FFPROBE_PROBE\')\n    probe=\'import torch,numpy,sentencepiece,ftfy; from diffusers import AutoencoderKL,AutoencoderKLWan,WanPipeline,UniPCMultistepScheduler\'\n    if logged([PYTHON,\'-c\',probe],\'DEPENDENCY_PROBE\',check=False):\n        logged([PYTHON,\'-m\',\'pip\',\'install\',\'torch\',\'numpy\',\'diffusers\',\'transformers\',\'accelerate\',\'safetensors\',\'huggingface-hub\',\'sentencepiece\',\'ftfy\'],\'DEPENDENCY_REPAIR\')\n        logged([PYTHON,\'-c\',probe],\'DEPENDENCY_REPROBE\')\n    try:\n        record=json.loads(subprocess.check_output([PYTHON,\'-c\',\'import json; from runtime.wan.provenance import source_identity; print(json.dumps(source_identity(".")))\'],cwd=REPO,text=True))\n        optional_record(OUTPUT/\'source_receipt.json\',record)\n    except Exception as exc:print(\'Optional source record unavailable:\',type(exc).__name__,str(exc))\n    try:(OUTPUT/\'environment_freeze.txt\').write_text(subprocess.check_output([PYTHON,\'-m\',\'pip\',\'freeze\'],text=True))\n    except Exception as exc:print(\'Optional environment record unavailable:\',type(exc).__name__,str(exc))\n    write_json(OUTPUT/\'setup_receipt.json\',dict(status=\'SETUP_COMPLETE\',source_dir=str(REPO),fixed_denominator=FIXED))\nexcept Exception as exc:\n    try:failed(\'SOURCE_OR_ENVIRONMENT\',exc)\n    except BaseException as record_error:\n        if hasattr(exc,\'add_note\'):exc.add_note(\'failure record error: \'+repr(record_error))\n    raise\n'

RUN = "try:\n    from google.colab import userdata\n    token=userdata.get('HF_TOKEN')\n    if token:os.environ['HF_TOKEN']=token\nexcept Exception:pass\nfinally:token=None\ncommand=[PYTHON,'-u','-m',ENTRYPOINT,'--config',str(CONFIG_PATH),'--output',str(RUN_OUTPUT)]\ntry:\n    validate_config()\n    returncode=logged(command,'FIXED_RUN',cwd=REPO,check=False)\n    print('Runner exit code:',returncode)\n    RESULT_PATH=RUN_OUTPUT/'result.json'\n    write_json(OUTPUT/'execution_receipt.json',dict(command=command,returncode=returncode,result_path=str(RESULT_PATH),result_exists=RESULT_PATH.is_file()))\n    if not RESULT_PATH.is_file():raise RuntimeError('No runner result; fixed denominator retained')\nexcept Exception as exc:\n    try:failed('RUNNER',exc)\n    except BaseException as record_error:\n        if hasattr(exc,'add_note'):exc.add_note('failure record error: '+repr(record_error))\n    raise\n"

DISPLAY = "result=json.loads(RESULT_PATH.read_text())\nif result['fixed_denominator']!=FIXED:raise RuntimeError('result fixed denominator mismatch')\nprint('Status:',result['status'],'Counts:',result.get('counts'),'Calls:',result.get('calls'))\nprint('Fixed denominator:',result['fixed_denominator'])\nfor sid,row in result.get('estimates',{}).items():\n    print('Estimate',sid,row)\nfor sid,row in result.get('sync_posthoc',result.get('path_posthoc',{})).items():\n    print('Sync/path posthoc',sid,row)\nfor lid,row in result.get('payload_posthoc',result.get('posthoc',{})).items():\n    margins=[x['signed_normalized_margin'] for x in row.get('bit_rows',[]) if 'signed_normalized_margin' in x]\n    print('Payload',lid,'key=',row.get('key_role'),'errors=',row.get('bit_errors'),'error_bits=',row.get('error_bits'),'minmargin=',min(margins,default=None),'alias=',row.get('alias_of'))\nprint('Failures:',result['failures'])\nprint('Result:',RESULT_PATH)\nprint('Execution evidence only; aliases are not independent observations; full readouts remain in result and sidecars.')\n"

def build(name,module,config,*,source_sha=None,output=None,media=False,description=None,display=None,cell_prefix='release'):
    cfg=json.loads((ROOT/config).read_text());fixed=cfg['fixed_denominator']
    markdown=(description or '# '+name)+f"\n\nSet SOURCE_DIR to available local source and CONFIG_PATH to an explicit JSON based on `{config}`. Keep its declared geometry and denominator. Provide required RGB paths and companion preparation/oracle/posthoc files where the entry uses them. SOURCE_URL is optional and used only when SOURCE_DIR does not exist. Existing source is never reset or overwritten. Source and environment identifiers are optional records.\n\nRun this Notebook against available source containing this entry. Engineering checks do not establish a successful model run. No implicit historical Drive inputs. Fixed denominator: {fixed}. All failure slots remain."
    prefix=f"SOURCE_DIR = '/content/SC-SSTW'  # Existing source, including an unpacked directory without .git.\nSOURCE_URL = None  # Optional explicit repository URL, only if SOURCE_DIR is absent.\nSOURCE_SHA = {source_sha!r}  # Optional location note; never checked.\nCONFIG_PATH = None  # Explicit user-supplied configuration.\nCONFIG_NAME = {cfg['name']!r}\nENTRYPOINT = {module!r}\nOUTPUT_ROOT = '/content/drive/MyDrive/Video-WM/{name}'\nFIXED = {fixed!r}\nREQUIRES_MEDIA = {media!r}\n"
    rows=[('code',"from google.colab import drive\ndrive.mount('/content/drive')\n"),('markdown',markdown),('code',prefix+SETUP),('code',ENVIRONMENT),('code',RUN),('code',display or DISPLAY)]
    cells=[]
    for i,(kind,source) in enumerate(rows):
        row=dict(cell_type=kind,id=cell_prefix+'-'+str(i),metadata={},source=source.splitlines(keepends=True))
        if kind=='code':ast.parse(source);row.update(outputs=[],execution_count=None)
        cells.append(row)
    nb=dict(nbformat=4,nbformat_minor=5,cells=cells,metadata=dict(kernelspec=dict(display_name='Python 3',language='python',name='python3'),language_info=dict(name='python'),candidate_binding=dict(candidate=name,source_sha=source_sha,status='OPTIONAL_LOCATION_RECORD')))
    path=Path(output);path.parent.mkdir(exist_ok=True,parents=True);path.write_text(json.dumps(nb,indent=1)+'\n');return path
